(()=>{const A='#ff86c2',reduce=matchMedia('(prefers-reduced-motion:reduce)').matches,b=document.body,s=document.createElement('style');s.textContent=`.fxbar{position:fixed;top:0;left:0;width:100%;height:2px;background:#fff1;z-index:100}.fxbar i{display:block;height:100%;width:0;background:${A};box-shadow:0 0 15px ${A}}.fx-heart{position:fixed;pointer-events:none;z-index:2;color:${A};opacity:0;animation:floatHeart 8s linear infinite}.fx-orb{position:fixed;border-radius:50%;pointer-events:none;filter:blur(80px);opacity:.12;z-index:-1}.fx-orb.a{width:340px;height:340px;left:-120px;top:20%;background:${A};animation:drift 13s ease-in-out infinite}.fx-orb.b{width:360px;height:360px;right:-150px;bottom:5%;background:#8d5bff;animation:drift 17s ease-in-out infinite reverse}.fxr{opacity:0;transform:translateY(38px) scale(.985);transition:1s cubic-bezier(.2,.8,.2,1)}.fxr.on{opacity:1;transform:none}@keyframes drift{50%{transform:translate(80px,-45px)}}@keyframes floatHeart{0%{transform:translateY(20vh) rotate(0);opacity:0}15%{opacity:.6}100%{transform:translateY(-110vh) rotate(240deg);opacity:0}}`;b.appendChild(s);const bar=document.createElement('div');bar.className='fxbar';bar.innerHTML='<i></i>';b.appendChild(bar);['a','b'].forEach(c=>{const o=document.createElement('div');o.className='fx-orb '+c;b.appendChild(o)});if(!reduce)for(let i=0;i<22;i++){const h=document.createElement('span');h.className='fx-heart';h.textContent=['♡','✦','·'][i%3];h.style.left=Math.random()*100+'%';h.style.fontSize=10+Math.random()*18+'px';h.style.animationDelay=-Math.random()*8+'s';b.appendChild(h)}document.querySelectorAll('section').forEach(e=>e.classList.add('fxr'));const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('on');io.unobserve(e.target)}}),{threshold:.1});document.querySelectorAll('.fxr').forEach(e=>io.observe(e));addEventListener('scroll',()=>{const m=document.documentElement.scrollHeight-innerHeight;bar.firstElementChild.style.width=(m?scrollY/m*100:0)+'%'})})();